import{_ as t,o,c as a,ag as r}from"./chunks/framework.BIas3y6W.js";const u=JSON.parse('{"title":"Project 2: An AI Micro-App (weeks 9–10)","description":"","frontmatter":{"source":"projects/ai-micro-app.md"},"headers":[],"relativePath":"projects/ai-micro-app.md","filePath":"projects/ai-micro-app.md"}'),s={name:"projects/ai-micro-app.md"};function i(n,e,d,h,l,c){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="project-2-an-ai-micro-app-weeks-910" tabindex="-1">Project 2: An AI Micro-App (weeks 9–10) <a class="header-anchor" href="#project-2-an-ai-micro-app-weeks-910" aria-label="Permalink to &quot;Project 2: An AI Micro-App (weeks 9–10)&quot;">​</a></h1><blockquote><p>A small web app that asks an AI model for help, where the secret key lives only on the server. Small app, big lesson: the browser is public.</p></blockquote><table tabindex="0"><thead><tr><th>Item</th><th>Details</th></tr></thead><tbody><tr><td><strong>Weeks</strong></td><td>9–10</td></tr><tr><td><strong>Repo</strong></td><td>Its own repo on your <strong>personal</strong> GitHub account (not an organization&#39;s), named after what it does, for example <code>fridge-chef</code></td></tr><tr><td><strong>Starter</strong></td><td><a href="https://github.com/Boyu-Zhang-UOI/vc101-micro-app-starter" target="_blank" rel="noreferrer"><code>weeks/09-apis-and-secrets/starter/</code></a> · <a href="./../setup/codespaces.html#start-a-project-from-a-starter">how to start from a starter</a></td></tr><tr><td><strong>Live at</strong></td><td>Your app&#39;s <strong>production URL</strong> on Vercel, for example <code>https://fridge-chef.vercel.app</code></td></tr><tr><td><strong>Tools</strong></td><td>GitHub Codespaces; a free LLM API key; Vercel. Current providers and fallbacks: <a href="./../TOOLS.html">Tool Handout</a></td></tr><tr><td><strong>Due</strong></td><td>End of week 10: before week 11 Studio A (default 11:59 pm the night before). Your <a href="./capstone.html#the-pitch">capstone pitch</a> is due earlier: <strong>72 hours before week 11 Studio A</strong></td></tr><tr><td><strong>Graded as</strong></td><td><a href="./../assessment/rubrics.html#project-2">Project 2 rubric</a> (15% of the course). This project is your homework for weeks 9 and 10, so those weeks have no other homework score, and week 10 has no separate reflection. Your <a href="./capstone.html#the-pitch">capstone pitch</a> is scored separately, in <a href="./../assessment/rubrics.html#capstone-pitch">Assignments</a></td></tr><tr><td><strong>Step-by-step labs</strong></td><td><a href="./../weeks/09-apis-and-secrets/">Week 9</a> · <a href="./../weeks/10-servers-and-deployment/">Week 10</a></td></tr></tbody></table><h2 id="what-youll-build" tabindex="-1">What you&#39;ll build <a class="header-anchor" href="#what-youll-build" aria-label="Permalink to &quot;What you&#39;ll build&quot;">​</a></h2><p>A one-screen app: the user types something, your server asks an <a href="./../resources/glossary.html#llm">LLM</a> (large language model, the kind of AI behind chat assistants) to do one job with it, and the page shows the answer. The starter already works as a &quot;Plain English&quot; explainer; you turn it into your own app.</p><p><strong>How one request travels</strong> (left to right, and back):</p><table tabindex="0"><thead><tr><th>Step</th><th>Where</th><th>Files</th><th>Who can read it</th></tr></thead><tbody><tr><td>1. The user types and clicks</td><td><strong>Browser</strong> (public)</td><td><code>public/index.html</code>, <code>public/app.js</code>, and the input rules in <code>public/lib/input.js</code></td><td>Anyone: every visitor can read these files with DevTools</td></tr><tr><td>2. The page sends the text to <code>/api/ask</code></td><td><strong>Your server</strong> (private)</td><td><code>api/ask.js</code> checks the input again; <code>lib/</code> adds the system prompt and the key</td><td>Only you and your host</td></tr><tr><td>3. Your server asks the model, with the key</td><td><strong>LLM provider</strong></td><td>—</td><td>The provider sees the text and your key</td></tr><tr><td>4. The answer comes back</td><td>Server, then browser, as JSON</td><td>—</td><td>The visitor sees the answer, never the key</td></tr></tbody></table><p>An <a href="./../resources/glossary.html#api-key">API key</a> is a password that lets a program use a paid or rate-limited service: &quot;a password with a bill attached&quot;. It lives in an <a href="./../resources/glossary.html#environment-variable">environment variable</a> (a setting the server reads when it starts, stored outside your code): in a <code>.env</code> file in your Codespace, and in Vercel&#39;s settings when deployed. The three settings are <code>LLM_BASE_URL</code>, <code>LLM_API_KEY</code> and <code>LLM_MODEL</code>. The <a href="https://github.com/Boyu-Zhang-UOI/vc101-micro-app-starter/blob/main/README.md" target="_blank" rel="noreferrer">starter README</a> explains every file.</p><h2 id="why-this-project" tabindex="-1">Why this project <a class="header-anchor" href="#why-this-project" aria-label="Permalink to &quot;Why this project&quot;">​</a></h2><ul><li><strong>Anything sent to the browser is public.</strong> Visitors can read every file in <code>public/</code> with their browser&#39;s DevTools. A secret key placed there is a key given away.</li><li><strong>This is how real apps leak.</strong> In 2025–26, many vibe-coded apps exposed their databases and keys because the browser was trusted with things only a server should hold. In one scan of apps built with Lovable, 170 of 1,645 had exposed databases (<a href="https://www.superblocks.com/blog/lovable-vulnerabilities" target="_blank" rel="noreferrer">Superblocks</a>). AI-assisted commits leak secrets about twice as often as ordinary ones (<a href="https://blog.gitguardian.com/the-state-of-secrets-sprawl-2026/" target="_blank" rel="noreferrer">GitGuardian 2026</a>).</li><li><strong>Tools change, so switching is a skill.</strong> Free AI providers change their limits often. Because the starter speaks one common request format, you can switch providers by changing settings, not code.</li></ul><h2 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h2><p>These match the core tier of the homework for <a href="./../weeks/09-apis-and-secrets/">week 9</a> and <a href="./../weeks/10-servers-and-deployment/">week 10</a>.</p><h3 id="1-start-from-the-starter-and-make-it-your-own" tabindex="-1">1. Start from the starter and make it your own <a class="header-anchor" href="#1-start-from-the-starter-and-make-it-your-own" aria-label="Permalink to &quot;1. Start from the starter and make it your own&quot;">​</a></h3><ul><li>☐ Create your repo from the <a href="https://github.com/Boyu-Zhang-UOI/vc101-micro-app-starter" target="_blank" rel="noreferrer">starter</a> on your <strong>personal</strong> account. (Vercel&#39;s free plan can&#39;t deploy private repos owned by an organization; see <a href="./../TOOLS.html">Tool Handout</a>.)</li><li>☐ Give the app <strong>one new job</strong>: change the <strong>system prompt</strong> in <code>lib/prompt.js</code> (your app&#39;s standing instructions to the model), the page text and the styling. Optionally add an input, such as a dropdown for tone or difficulty.</li><li>☐ Optional, and good practice for the capstone: a half-page <code>SPEC.md</code> with the problem, the user and three acceptance criteria, one of them an edge case.</li></ul><h3 id="2-keep-the-key-on-the-server" tabindex="-1">2. Keep the key on the server <a class="header-anchor" href="#2-keep-the-key-on-the-server" aria-label="Permalink to &quot;2. Keep the key on the server&quot;">​</a></h3><ul><li>☐ Your key is in <code>.env</code> (in your Codespace) and in Vercel&#39;s environment variables (in production). <strong>Nowhere else.</strong></li><li>☐ <code>.env</code> is listed in <code>.gitignore</code>, and <code>.env.example</code> holds only placeholders.</li><li>☐ Nothing under <code>public/</code> mentions the key. Only server code (<code>api/</code> and <code>lib/</code>) reads <code>process.env</code>.</li><li>☐ You checked: <code>npm run check:secrets</code> finds nothing (it scans your files <strong>and your git history</strong>), and on the <strong>production</strong> site, DevTools → Sources and Network show no key.</li><li>☐ You did the <strong>hidden-costs checklist</strong> from the homework, including a hard spending cap (on a free tier, the simplest cap is having no payment method on the account; see <a href="./../setup/safety-contract.html">safety contract</a> rule 4).</li></ul><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check:secrets</span></span></code></pre></div><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p>Never paste your key into a chat assistant, a prompt, an issue or a screenshot. If it ever lands in a commit (even one you later deleted) or in a chat, <strong>revoke it</strong> on the provider&#39;s dashboard and create a new one. Deleting it from the code isn&#39;t enough: old commits stay readable.</p></div><h3 id="3-swap-providers-by-changing-configuration-only" tabindex="-1">3. Swap providers by changing configuration only <a class="header-anchor" href="#3-swap-providers-by-changing-configuration-only" aria-label="Permalink to &quot;3. Swap providers by changing configuration only&quot;">​</a></h3><ul><li>☐ Run your app with <strong>two different LLM providers</strong>, changing only the three environment variables. No code changes.</li><li>☐ Find valid model names with <code>npm run models</code>, not from memory or from an AI&#39;s guess.</li><li>☐ Log the swap in <code>PROMPTS.md</code>: which providers, which models, what you changed, and how the answers differed.</li></ul><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> models</span></span></code></pre></div><h3 id="4-keep-the-limits-and-make-them-yours" tabindex="-1">4. Keep the limits, and make them yours <a class="header-anchor" href="#4-keep-the-limits-and-make-them-yours" aria-label="Permalink to &quot;4. Keep the limits, and make them yours&quot;">​</a></h3><p>A public page that spends your key is an invitation: anyone who finds the URL can use up your free quota. The starter already protects itself. Its input rules in <code>public/lib/input.js</code> run in the browser <strong>and again on the server</strong>, and <code>api/ask.js</code> turns provider problems into friendly messages. Your job is to keep that protection working as you change the app, and to make it fit your app.</p><ul><li>☐ <strong>Your own input limit.</strong> Set <code>MAX_INPUT_LENGTH</code> to a length that suits your app&#39;s job, and say why in <code>PROMPTS.md</code>. If you add an input, the server must check it too: a check in the browser alone doesn&#39;t count, because anyone can call <code>/api/ask</code> directly.</li><li>☐ <strong>Tried each error on purpose:</strong> empty input, input that&#39;s too long, and a missing or wrong key (rename <code>LLM_API_KEY</code> in <code>.env</code> for a minute). Each shows a friendly message, and the technical details stay in the server log.</li></ul><h3 id="5-test-it" tabindex="-1">5. Test it <a class="header-anchor" href="#5-test-it" aria-label="Permalink to &quot;5. Test it&quot;">​</a></h3><ul><li>☐ <code>npm test</code> passes, including the starter&#39;s tests.</li><li>☐ <strong>At least two validation tests of your own</strong>, written by you, in <code>tests/my-limit.test.js</code> (<a href="./../weeks/10-servers-and-deployment/homework.html">week 10 homework</a>): for example, &quot;a question one character over my limit is rejected&quot;. Tests must not call the real API or need a key.</li></ul><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span></span></code></pre></div><h3 id="6-deploy-on-vercel" tabindex="-1">6. Deploy on Vercel <a class="header-anchor" href="#6-deploy-on-vercel" aria-label="Permalink to &quot;6. Deploy on Vercel&quot;">​</a></h3><ul><li>☐ <strong>Test locally first:</strong> the app works in your Codespace (<code>npm run dev</code>) with <code>npm test</code> passing, before you deploy.</li><li>☐ The app is live on Vercel, with the three environment variables set in the Vercel project&#39;s settings.</li><li>☐ You tried the <strong>production URL</strong> in a private window: one normal request and one edge case (empty or too long).</li><li>☐ You took a <strong>screenshot</strong> of the production site working. Submit the production URL, not a preview link: Vercel deletes old preview deployments.</li></ul><h3 id="7-document-it" tabindex="-1">7. Document it <a class="header-anchor" href="#7-document-it" aria-label="Permalink to &quot;7. Document it&quot;">​</a></h3><ul><li>☐ <code>README.md</code> with the production URL, a description of <strong>your</strong> app, and the section <strong>&quot;Where the key lives and who can read it&quot;</strong> (below). 🔴 <strong>AI off:</strong> you write that section yourself. It takes the place of a week 10 reflection.</li><li>☐ <code>PROMPTS.md</code> with your key prompts, the provider-swap entry, and what you checked yourself.</li></ul><h2 id="where-the-key-lives-and-who-can-read-it" tabindex="-1">&quot;Where the key lives and who can read it&quot; <a class="header-anchor" href="#where-the-key-lives-and-who-can-read-it" aria-label="Permalink to &quot;&quot;Where the key lives and who can read it&quot;&quot;">​</a></h2><p>This README section is the week 10 understanding check in writing. The starter&#39;s README has an empty section with this name. 🔴 <strong>AI off:</strong> write it yourself, in your own words. It must answer:</p><ol><li>Where is the key stored in your Codespace, and why doesn&#39;t git save it?</li><li>Where is it stored for the live site?</li><li>Which file reads it, and how? (Name the file and the environment variable.)</li><li>Who can read the key? Who can&#39;t?</li><li>What can a visitor with DevTools see, and what can&#39;t they see?</li><li>How did you check that the key isn&#39;t in the browser or in your git history? (Paste the <code>npm run check:secrets</code> result.)</li><li>What would you do if the key leaked?</li></ol><h2 id="week-10-calling-someone-elses-api" tabindex="-1">Week 10: calling someone else&#39;s API <a class="header-anchor" href="#week-10-calling-someone-elses-api" aria-label="Permalink to &quot;Week 10: calling someone else&#39;s API&quot;">​</a></h2><p>In week 10 you also add a second kind of server route: one that fetches live data from a <strong>public API</strong> that needs no key (weather, public holidays, books). It isn&#39;t part of Project 2&#39;s grade, but it&#39;s the pattern behind capstone feature type (d), and the capstone starter has a tested example, <code>api/weather.js</code> (<a href="https://github.com/Boyu-Zhang-UOI/vc101-capstone-starter/blob/main/README.md#feature-patterns" target="_blank" rel="noreferrer">feature patterns</a>). Things to handle: the other service may be slow, down or rate-limited, so check the response status, give up after a timeout, and show a friendly message.</p><h2 id="stretch-optional-not-graded" tabindex="-1">Stretch (optional, not graded) <a class="header-anchor" href="#stretch-optional-not-graded" aria-label="Permalink to &quot;Stretch (optional, not graded)&quot;">​</a></h2><ul><li><strong>Your own friendly rate-limit message.</strong> When the provider says &quot;too many requests&quot; (status 429, a <a href="./../resources/glossary.html#rate-limit">rate limit</a>), rewrite the page&#39;s message so it says what happened and what to do next, in your app&#39;s voice.</li><li><strong>Keep the public-API route</strong> from week 10 in your micro-app, with a test that uses a fake (mocked) response.</li></ul><h2 id="ideas" tabindex="-1">Ideas <a class="header-anchor" href="#ideas" aria-label="Permalink to &quot;Ideas&quot;">​</a></h2><p>One input, one call to the model, one answer. Resist adding a second feature until the first one is safe and tested.</p><table tabindex="0"><thead><tr><th>App</th><th>The user types</th><th>The app returns</th></tr></thead><tbody><tr><td>Fridge chef</td><td>what&#39;s in the fridge</td><td>one simple recipe</td></tr><tr><td>Plain-English explainer</td><td>a term from a class or article</td><td>an explanation plus one example</td></tr><tr><td>Quiz me</td><td>a paragraph of their own notes</td><td>three multiple-choice questions</td></tr><tr><td>Kinder words</td><td>a blunt message</td><td>the same message, politer</td></tr><tr><td>Commit coach</td><td>a description of a code change</td><td>a clear commit message</td></tr><tr><td>Error explainer</td><td>an error message (never one containing a key)</td><td>what it probably means and where to look</td></tr><tr><td>Trip packer</td><td>a trip description</td><td>a packing checklist</td></tr><tr><td>Name machine</td><td>a description of a pet, band or project</td><td>five name ideas</td></tr><tr><td>Study planner</td><td>an exam date and topics</td><td>a five-day plan</td></tr><tr><td>Haiku of the day</td><td>three words about their day</td><td>a haiku</td></tr></tbody></table><p>Label AI answers as AI-generated, and don&#39;t build anything that gives medical, legal or financial advice.</p><h2 id="ai-use-on-this-project" tabindex="-1">AI use on this project <a class="header-anchor" href="#ai-use-on-this-project" aria-label="Permalink to &quot;AI use on this project&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Label</th><th>On the micro-app</th></tr></thead><tbody><tr><td>🟢 <strong>AI on</strong></td><td>Building, explaining, planning, reviewing your diffs, suggesting test cases</td></tr><tr><td>🟡 <strong>AI limited</strong></td><td>Your capstone pitch: the AI may critique it, not write it</td></tr><tr><td>🔴 <strong>AI off</strong></td><td>The README section &quot;Where the key lives and who can read it&quot;; the &quot;What I wrote or decided myself&quot; section of <code>PROMPTS.md</code>; the exit ticket</td></tr></tbody></table><h2 id="privacy" tabindex="-1">Privacy <a class="header-anchor" href="#privacy" aria-label="Permalink to &quot;Privacy&quot;">​</a></h2><ul><li>Free LLM tiers may use what users type for training, and humans may review it (<a href="./../TOOLS.html">Tool Handout</a> lists which). Add a line to your page such as &quot;Don&#39;t type personal information&quot;, and use made-up examples in your demo and screenshot.</li><li>Some free tiers may not serve users in certain regions or under 18. If that applies to your cohort, your instructor has an adjusted tool list.</li></ul><h2 id="after-the-course" tabindex="-1">After the course <a class="header-anchor" href="#after-the-course" aria-label="Permalink to &quot;After the course&quot;">​</a></h2><p>Your live app keeps spending your key for as long as it&#39;s up. When you no longer need it, remove the key from Vercel&#39;s settings or revoke it.</p><h2 id="how-its-graded" tabindex="-1">How it&#39;s graded <a class="header-anchor" href="#how-its-graded" aria-label="Permalink to &quot;How it&#39;s graded&quot;">​</a></h2><p>The <a href="./../assessment/rubrics.html#project-2">Project 2 rubric</a> scores keeping the key on the server (the biggest row), your input limit and friendly errors, the provider swap, making it your own and deploying it (production URL and screenshot), and your documentation and tests. Project 2 is 15% of the course. The capstone pitch, due the same week, is scored in <a href="./../assessment/rubrics.html#capstone-pitch">Assignments</a>.</p><h2 id="submit" tabindex="-1">Submit <a class="header-anchor" href="#submit" aria-label="Permalink to &quot;Submit&quot;">​</a></h2><p>Follow <a href="./#how-to-submit">How to submit</a>: on Canvas, the repo URL, the <strong>production URL and a screenshot</strong> of it working, and the link to your final commit. Submit your <a href="./capstone.html#the-pitch">capstone pitch</a> separately on Canvas, 72 hours before week 11 Studio A.</p><h2 id="if-you-get-stuck" tabindex="-1">If you get stuck <a class="header-anchor" href="#if-you-get-stuck" aria-label="Permalink to &quot;If you get stuck&quot;">​</a></h2><ul><li><strong>Error messages from the app</strong> (&quot;not set up yet&quot;, &quot;rejected the server&#39;s API key&quot;, &quot;could not find that model&quot;, &quot;quota is used up&quot;): the <a href="https://github.com/Boyu-Zhang-UOI/vc101-micro-app-starter/blob/main/README.md#troubleshooting" target="_blank" rel="noreferrer">starter README&#39;s troubleshooting table</a> says what each means and what to do.</li><li><strong>Works in the Codespace, fails on Vercel:</strong> usually a missing environment variable on Vercel. Add it, then redeploy. More: <a href="./../resources/troubleshooting.html#deploying-to-vercel">Deploying to Vercel</a>.</li><li><strong>Rate limit (429):</strong> wait, or switch provider; that&#39;s the drill. See <a href="./../resources/troubleshooting.html#i-ran-out-of-free-credits">I ran out of free credits</a>.</li><li><strong>Never</strong> paste your key into a chat or an issue to ask for help. Describe the error message instead.</li><li>More help: <a href="./../resources/troubleshooting.html">troubleshooting</a>.</li></ul>',54)])])}const g=t(s,[["render",i]]);export{u as __pageData,g as default};
